    const scan = m.commands.find((c) => c.name === "scan")!;
    expect(scan).toBeDefined();
    expect(scan.exit_codes["0"]).toBeDefined();
    expect(scan.exit_codes["1"]).toBeDefined();
    expect(scan.exit_codes["2"]).toBeDefined();
