1→import { defineCommand } from "citty";
import { resolve } from "path";
import pc from "picocolors";
import { isCancel, select, spinner } from "@clack/prompts";
import { listReviewTargets, review, type ReviewResult, type ReviewFinding } from "../../core/review.js";

import { ui, renderCheck, resolveOutputMode, outJson, emitError, nextAction, summaryLine } from "../out.js";
import { preflight, reviewPreflightMessage } from "../preflight.js";
import { exit } from "../render/exit.js";
10→import { getFindingDocUrl } from "../../core/doc-registry.js";

/**
 * Dim Docs: line under non-pass findings that lack a public rule code.
 * Coded findings already surface R0xx on the line — full URLs stay in JSON.
 */
function renderFindingDocs(f: ReviewFinding, indent = 6): void {
  if (f.severity === "pass") return;
  if (publicRuleCode(f)) return;
  const url = f.docUrl ?? getFindingDocUrl({ code: f.code ?? f.id, tier: f.tier });
20→  if (url) ui.dim(`${" ".repeat(indent)}Docs: ${url}`);
}

// ── Rendering ──────────────────────────────────────────────────────────────────

function countParts(p: number, w: number, e: number): string {
  const parts: string[] = [];
  if (p > 0) parts.push(pc.green(`✓ ${p} passed`));
  if (w > 0) parts.push(pc.yellow(`⚠ ${w} warning${w === 1 ? "" : "s"}`));
  if (e > 0) parts.push(pc.red(`✗ ${e} error${e === 1 ? "" : "s"}`));
30→  return parts.join(" · ");
}

function renderTierLine(name: string, passed: number, warnings: number, errors: number): void {
  ui.write(`  ${name.padEnd(18)} ${countParts(passed, warnings, errors)}`);
}

export function severityLabel(severity: ReviewFinding["severity"]): string {
  return severity === "info" ? "FYI" : severity;
}
40→
/** Public rule codes look like R014 — lead with them so review teaches identity. */
export function publicRuleCode(f: Pick<ReviewFinding, "code">): string | undefined {
  const code = f.code?.trim();
  return code && /^R\d{3}$/.test(code) ? code : undefined;
}

/** Human finding text: `R014  message` when coded; message alone otherwise. */
export function formatFindingText(f: Pick<ReviewFinding, "code" | "message">): string {
  const code = publicRuleCode(f);
50→  return code ? `${code}  ${f.message}` : f.message;
}

function renderOneFinding(f: ReviewFinding): void {
  if (f.severity === "pass") return;
  const text = formatFindingText(f);
  if (f.severity === "info") ui.dim(`    ${severityLabel(f.severity)}  ${text}`);
  else renderCheck(f.severity === "error" ? "fail" : "warn", text, 4);
  renderFindingDocs(f, 6);
}
60→
function renderFindings(findings: ReviewFinding[]): void {
  for (const f of findings) renderOneFinding(f);
}

function renderOptionalTier(
  name: string,
  tier?: { available: boolean; method?: string; count?: number; findings?: ReviewFinding[] },
): void {
  if (!tier || !tier.available) {
70→    const reason = name === "LLM review" ? "no judge found" : "no session files";
    ui.write(`  ${name.padEnd(18)} ${pc.dim(`unavailable (${reason})`)}`);
    return;
  }
  const label =
    name === "LLM review" && tier.method
      ? `via ${tier.method}`
      : `${tier.count ?? tier.findings?.length ?? 0} sessions found`;
  ui.write(`  ${name.padEnd(18)} ${label}`);
  for (const f of tier.findings ?? []) renderOneFinding(f);
80→}

