    expect(resolveOutputMode({ format: "table", ci: true })).toEqual({ format: "json", ci: true });
  });

  test("unknown format falls back to table", () => {
    expect(resolveOutputMode({ format: "yaml" })).toEqual({ format: "table", ci: false });
  });
});

